// TaskDetail is the full task view model.
type TaskDetail struct {
	ID            string
	ProjectID     string
	Key           string
	Title         string
	Description   string
	Points        int
	Priority      int
	PriorityLabel string
	Status        string
	DueAt         string
	Assignees     []AssigneeRow
	Labels        []LabelRow
	Watchers      []WatcherRow
	Relations     []RelationRow
	Attachments   []AttachmentRow
	Runs          []RunThreadRow
}

// AttachmentRow is a file attached to a task.
type AttachmentRow struct {
	ID        string
	Filename  string
	Mime      string
	Size      int64
	CreatedAt string
}

// CommentRow is a single comment in the thread.
type CommentRow struct {
	ID        string
	Author    string
	Body      string
	CreatedAt string
	CanEdit   bool
}

// ActivityRow is a single activity entry.
type ActivityRow struct {
	Actor     string
	Action    string
	CreatedAt string
}

// RunThreadRow is a single agent run on a task's thread (WU-307).
type RunThreadRow struct {
	ID        string
	AgentName string
	Trigger   string
	Status    string
	Error     string
	Steps     []ThreadStepRow
}

// ThreadStepRow is one step within a run thread.
type ThreadStepRow struct {
	Seq      int64
	Kind     string
	Request  string
	Response string
}

// AssigneeRow is an assigned user.
type AssigneeRow struct {
	Name    string
	ID      string
	Initial string
}

// LabelRow is a label applied to the task.
type LabelRow struct {
	Name  string
	Color string
}

// WatcherRow is a watching user.
type WatcherRow struct {
	Name string
	ID   string
}

// RelationRow is a related task link.
type RelationRow struct {
	RelatedKey   string
	RelationType string
}

