// PriorityLabel returns a human-friendly priority string.
func priorityLabel(p int) string {
	switch p {
	case 0:
		return "none"
	case 1:
		return "low"
	case 2:
		return "medium"
	case 3:
		return "high"
	case 4:
		return "critical"
	default:
		return "none"
	}
}

